 private async upsertImportUnitsAndBarcode(tx:Tx,companyId:string,productId:string,row:CompanyImportRow){let base=await tx.productUnit.findFirst({where:{productId,active:true,isBase:true}});if(row.baseUnitName?.trim()){if(base)base=await tx.productUnit.update({where:{id:base.id},data:{name:row.baseUnitName.trim(),version:{increment:1}}});else base=await tx.productUnit.create({data:{productId,name:row.baseUnitName.trim(),conversionFactor:new Prisma.Decimal(1),isBase:true,defaultSale:true,defaultPurchase:!row.packageUnitName}});}let target=base;if(row.packageUnitName?.trim()){const factor=new Prisma.Decimal(row.packageFactor?.trim()||'1');target=await tx.productUnit.findFirst({where:{productId,name:row.packageUnitName.trim(),active:true}})??await tx.productUnit.create({data:{productId,name:row.packageUnitName.trim(),conversionFactor:factor,defaultPurchase:true}});}if(row.barcode&&target){const value=normalizeBarcode(row.barcode);const existing=await tx.productBarcode.findUnique({where:{companyId_value:{companyId,value}}});if(existing&&existing.productId!==productId)throw new ProductPersistenceConflictError('Barcode belongs to another product');if(existing)await tx.productBarcode.update({where:{id:existing.id},data:{unitId:target.id,symbology:row.barcodeSymbology??existing.symbology,active:true,version:{increment:1}}});else await tx.productBarcode.create({data:{companyId,productId,unitId:target.id,value,symbology:row.barcodeSymbology??null,source:'import'}});}}
