 private centralMatches(r:CentralRow,q:CentralSearchQuery){return(!q.status||r.status===q.status)&&(!q.manufacturer||r.manufacturerName?.toLocaleLowerCase().includes(q.manufacturer.toLocaleLowerCase()))&&(!q.dosageForm||r.dosageForm?.toLocaleLowerCase().includes(q.dosageForm.toLocaleLowerCase()))&&(q.controlled===undefined||r.controlled===q.controlled);}
 private async applyCentralPackaging(tx:Tx,p:ProductRow,c:CentralRow){const base=p.units.find(x=>x.active&&x.isBase);if(c.baseUnitLabel){if(base)await tx.productUnit.update({where:{id:base.id},data:{name:c.baseUnitLabel,version:{increment:1}}});else await tx.productUnit.create({data:{productId:p.id,name:c.baseUnitLabel,conversionFactor:new Prisma.Decimal(1),isBase:true,defaultSale:true}});}if(c.packageUnitLabel&&c.conversionFactor){const pack=p.units.find(x=>x.active&&!x.isBase&&x.conversionFactor.equals(c.conversionFactor!));if(pack)await tx.productUnit.update({where:{id:pack.id},data:{name:c.packageUnitLabel,conversionFactor:c.conversionFactor,version:{increment:1}}});else await tx.productUnit.create({data:{productId:p.id,name:c.packageUnitLabel,conversionFactor:c.conversionFactor,defaultPurchase:true}});}}
 private async applyCentralBarcodes(tx:Tx,companyId:string,p:ProductRow,c:CentralRow){const target=p.units.find(x=>x.active&&!x.isBase)??p.units.find(x=>x.active&&x.isBase);if(!target&&c.barcodes.length)throw new ProductClassificationError('Product needs an active unit before applying central barcodes');await tx.productBarcode.deleteMany({where:{productId:p.id}});for(let i=0;i<c.barcodes.length;i++){const b=c.barcodes[i]!;await tx.productBarcode.create({data:{companyId,productId:p.id,unitId:target!.id,value:b.value,symbology:b.symbology,isPrimary:i===0,active:true,source:`central:${c.sourceId}`}});}}
 private unique(e:unknown){return e instanceof Prisma.PrismaClientKnownRequestError&&e.code==='P2002';}
 private throwPersistence(e:unknown):never{if(e instanceof ProductConcurrentUpdateError||e instanceof ProductClassificationError||e instanceof ProductPersistenceConflictError)throw e;if(e instanceof Prisma.PrismaClientKnownRequestError){if(e.code==='P2002')throw new ProductPersistenceConflictError('Unique product, barcode, regulatory identifier, central reference, or master value already exists');if(e.code==='P2025')throw new ProductClassificationError('Requested Products record does not exist in the authorized scope');if(e.code==='P2003')throw new ProductClassificationError('Referenced Products master record is invalid');}throw e;}
